<?php
namespace App\Actions\ServiceOrders;use App\Domain\ServiceOrders\ServiceOrderStatusTransition;use App\Enums\{ServiceOrderStatus,TechnicianAssignmentStatus,TechnicianWorkingStatus};use App\Models\{ServiceOrder,ServiceOrderStatusHistory};use Illuminate\Support\Facades\DB;
class CancelServiceOrder{public function execute(ServiceOrder $order):ServiceOrder{return DB::transaction(function()use($order){$o=ServiceOrder::lockForUpdate()->findOrFail($order->id);$old=(string)$o->status;if($old===ServiceOrderStatus::CANCELLED)return $o;app(ServiceOrderStatusTransition::class)->assertAllowed($old,ServiceOrderStatus::CANCELLED);$active=$o->assignments()->whereIn('status',[TechnicianAssignmentStatus::ASSIGNED,TechnicianAssignmentStatus::ACCEPTED,TechnicianAssignmentStatus::IN_PROGRESS])->get();foreach($active as $a){$wasBusy=(string)$a->status===TechnicianAssignmentStatus::IN_PROGRESS;$a->update(['status'=>TechnicianAssignmentStatus::CANCELLED]);if($wasBusy)$a->technician()->update(['working_status'=>TechnicianWorkingStatus::AVAILABLE]);}$o->update(['status'=>ServiceOrderStatus::CANCELLED,'cancelled_at'=>now()]);ServiceOrderStatusHistory::create(['service_order_id'=>$o->id,'old_status'=>$old,'new_status'=>ServiceOrderStatus::CANCELLED]);return $o->refresh();});}}
